```tsx
// ErrorBoundary.tsx
import React, { Component, ErrorInfo, ReactNode } from 'react';

interface Props {
  children: ReactNode;
  fallback?: (error: Error, retry: () => void) => ReactNode;
  onError?: (error: Error, info: ErrorInfo) => void;
}

interface State {
  error: Error | null;
  errorInfo: ErrorInfo | null;
}

export class ErrorBoundary extends Component<Props, State> {
  state: State = { error: null, errorInfo: null };

  static getDerivedStateFromError(error: Error): Partial<State> {
    return { error };
  }

  componentDidCatch(error: Error, info: ErrorInfo) {
    this.setState({ errorInfo: info });

    const { onError } = this.props;
    if (onError) {
      onError(error, info);
    } else {
      console.error('[ErrorBoundary] Caught render error:', {
        message: error.message,
        stack: error.stack,
        componentStack: info.componentStack,
        timestamp: new Date().toISOString(),
      });
    }
  }

  retry = () => this.setState({ error: null, errorInfo: null });

  render() {
    const { error } = this.state;
    const { children, fallback } = this.props;

    if (!error) return children;

    if (fallback) return fallback(error, this.retry);

    return <DefaultFallback error={error} retry={this.retry} />;
  }
}

function DefaultFallback({ error, retry }: { error: Error; retry: () => void }) {
  return (
    <div role="alert" style={styles.container}>
      <h2 style={styles.title}>Something went wrong</h2>
      <p style={styles.message}>{error.message}</p>
      <button onClick={retry} style={styles.button}>
        Try again
      </button>
      {process.env.NODE_ENV === 'development' && (
        <pre style={styles.stack}>{error.stack}</pre>
      )}
    </div>
  );
}

const styles: Record<string, React.CSSProperties> = {
  container: {
    padding: '2rem',
    border: '1px solid #f5c2c7',
    borderRadius: '8px',
    background: '#fff3f3',
    color: '#842029',
    maxWidth: '600px',
    margin: '2rem auto',
    fontFamily: 'sans-serif',
  },
  title: { margin: '0 0 0.5rem', fontSize: '1.25rem' },
  message: { margin: '0 0 1rem', fontSize: '0.95rem' },
  button: {
    padding: '0.5rem 1.25rem',
    background: '#842029',
    color: '#fff',
    border: 'none',
    borderRadius: '4px',
    cursor: 'pointer',
    fontSize: '0.9rem',
  },
  stack: {
    marginTop: '1rem',
    padding: '0.75rem',
    background: '#f8d7da',
    borderRadius: '4px',
    fontSize: '0.75rem',
    overflowX: 'auto',
    whiteSpace: 'pre-wrap',
  },
};
```

**Usage:**

```tsx
// Wrap any subtree — errors bubble up to the nearest boundary
<ErrorBoundary>
  <MyComponent />
</ErrorBoundary>

// Custom fallback UI
<ErrorBoundary
  fallback={(error, retry) => (
    <div>
      <p>Oops: {error.message}</p>
      <button onClick={retry}>Retry</button>
    </div>
  )}
  onError={(error, info) => Sentry.captureException(error, { extra: info })}
>
  <MyComponent />
</ErrorBoundary>
```

**Key design decisions:**

| Feature | Detail |
|---|---|
| `getDerivedStateFromError` | Captures error during render phase (required for class boundary) |
| `componentDidCatch` | Logs after commit — safe for side effects |
| `retry()` | Resets state, forcing children to remount |
| `onError` prop | Override default `console.error` (e.g. Sentry) |
| `fallback` prop | Custom UI while keeping boundary logic centralized |
| Stack trace | Dev-only via `NODE_ENV` check |

Error boundaries must be class components — hooks can't catch render errors in siblings/children.
